<your_rewritten_code_3>
</perturbed_code_3>
<perturbed_code_4>
<your_rewritten_code_4>
</perturbed_code_4>
<perturbed_code_5>
<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to rewrite:
<original_code>
#include <cstdio>
#include <vector>
#include <algorithm>
#include <cstring>
#include <queue>
using namespace std;

#define NN 202
#define F first
#define S second
#define mp make_pair
#define INF 0x3f3f3f3f // infinito da distancia

int flow[NN][NN]; // zerar antes (para 0..)
int cap[NN][NN]; // preencher com as capacidades, deixar 0 se nao tiver ligacao
int pre[NN], que[NN], d[NN]; // anteriores, fila, distancia

int edmondsKarp(int n, int source, int sink) // nao testa se source == sink
{
	int p, q, t, i, j;
	while (1)
	{
		memset(pre, -1, sizeof(pre));
		d[source] = INF;
		p = q = 0, que[q++] = source;
		while (p<q && pre[sink] < 0) // bfs
		{
			t = que[p++]; // facil de trocar por uma lista de adjacencia, so arrumar \/
			for (i=0; i<n; i++) if (pre[i]<0 && (j=cap[t][i]-flow[t][i])) 
				pre[que[q++]=i]=t, d[i]=min(d[t],j);
		}
		if (pre[sink]<0) break;
		for (i=sink; i!=source; i=pre[i]) flow[pre[i]][i]+=d[sink],flow[i][pre[i]]-=d[sink];
	}
	for (j=i=0; i<n; j+=flow[source][i++]);
	return j;
}

char a[11][11];
char b[11][11];
int bi, bj, dir[][2] = {0,1,0,-1,1,0,-1,0};
int mat[101][101];
int n, t;
vector<int> ca, cb, cc;

void solve(int A, int B, int* vis, bool check)
{
	queue<pair<int, int> > que;
	vis[A*n+B] = 0;
	que.push(mp(A, B));
	while (!que.empty())
	{
		pair<int, int> now = que.front();
		que.pop();
		int p = now.F*n+now.S;
		int dis = vis[p];
		if (check && (mat[bi*n+bj][p] <= dis || t <= dis))
		{
			if (mat[bi*n+bj][p] < dis || t < dis) vis[p] = INF+1;
			continue;
		}
		for (int d = 0; d < 4; ++d)
		{
			int i = dir[d][0]+now.F;
			int j = dir[d][1]+now.S;
			if (i < 0 || j < 0 || i == n || j == n) continue;
			if (b[i][j] < '0' || b[i][j] > '9') continue;
			int q = i*n+j;
			if (vis[q] != INF) continue;
			vis[q] = dis+1;
			que.push(mp(i, j));
		}
	}
}

void build()
{
	for (int i = 0; i < n; ++i)
	{
		for (int j = 0; j < n; ++j)
		{
			if (b[i][j] <= '0' || b[i][j] > '9') continue;
			ca.push_back(i);
			cb.push_back(j);
			int p = i*n+j;
			cap[p+2+n*n][1] = b[i][j]-'0';	
		}
	}
	int z = bi*n+bj;
	for (int i = 0; i < n; ++i)
	{
		for (int j = 0; j < n; ++j)
		{
			if (a[i][j] <= '0' || a[i][j] > '9') continue;
			int p = i*n+j;
			cap[0][p+2] = a[i][j]-'0';
			for (int k = 0; k < ca.size(); ++k)
			{
				int ii = ca[k];
				int jj = cb[k];
				int q = ii*n+jj;
				if (mat[p][q] < INF)
					cap[p+2][q+2+n*n] = INF;
			}
		}
	}
}

int main()
{
	scanf("%d%d", &n, &t);
	memset(mat, 0x3f, sizeof mat);
	for (int i = 0; i < n; ++i)
		scanf("%s", a[i]);
	for (int i = 0; i < n; ++i)
		scanf("%s", b[i]);
	for (int i = 0; i < n; ++i)
	{
		for (int j = 0; j < n; ++j)
		{
			if (a[i][j] == 'Z') bi = i, bj = j;
		}
	}
	solve(bi, bj, mat[bi*n+bj], false);
	for (int i = 0; i < n; ++i)
		for (int j = 0; j < n; ++j) if (a[i][j] >= '1' && a[i][j] <= '9')
			solve(i, j, mat[i*n+j], true);
	build();
	/*for (int i = 2; i < n*n+2; ++i) 
		for (int j = 2; j < n*n+2; ++j) if (cap[i][j] == INF)
			printf("link %d to %d\n", i-2, j-2);
	for (int i = 2; i < n*n+2; ++i)
		printf("cap from %d is %d\n", i-2, cap[0][i]);
	for (int i = 2; i < n*n+2; ++i)
		printf("cap to %d is %d\n", i-2, cap[i][1]);*/
	printf("%d\n", edmondsKarp(2+n*n+n*n, 0, 1));
}

